INSERT INTO figures (id, name, name_alt, years, era, region, role, tags, bio, relation, story, image, mds, dlabels, dkinds, note, relations, rel_notes) VALUES
  (51, '奥古斯都', 'Augustus', '前63—14', '古罗马', '罗马', '皇帝', ARRAY['帝王', '罗马', '军事'], '罗马帝国的开国君主，屋大维的尊号。他在内战废墟上确立元首制，开创近两百年的罗马和平，并改革行政与军事。', '御前管房', '', 'assets/figures/augustus.jpg', ARRAY['09-23', '09-02'], ARRAY['诞辰 · 前63年9月23日', '亚克兴海战 · 前31年9月2日'], ARRAY['birth', 'event'], '他清查户口的那年，你是被登记在帕拉蒂尼山最前面的一户。', ARRAY['御前管房', '罗马房东'], ARRAY['他清查户口的那年，你是被登记在帕拉蒂尼山最前面的一户。', '帕拉蒂尼山上的客房归你管，客人从没断过，连他自己也来蹭饭。']),
  (52, '提比略', 'Tiberius', '前42—37', '古罗马', '罗马', '皇帝', ARRAY['帝王', '罗马', '军事'], '罗马第二任皇帝，能干的统帅却多疑孤僻。晚年退隐卡普里岛，将政务委于近卫军长官，史评毁誉参半。', '卡普里岛船夫', '', 'assets/figures/tiberius.jpg', ARRAY['11-16', '09-18'], ARRAY['诞辰 · 前42年11月16日', '继位 · 14年9月18日'], ARRAY['birth', 'throne'], '他退隐到岛上那年，渡船的桨只有你划得动。', ARRAY['卡普里岛船夫', '近卫军书记'], ARRAY['他退隐到岛上那年，渡船的桨只有你划得动。', '宫里人人自危，唯独你敢替他抄写那些不能见光的密报。']),
  (53, '克劳狄乌斯', 'Claudius', '前10—54', '古罗马', '罗马', '皇帝', ARRAY['帝王', '罗马', '学者'], '罗马皇帝，因体弱曾被家族轻视，却意外登基。他勤于政务、主持征服不列颠，还留下多部失传的历史著作。', '不列颠向导', '', 'assets/figures/claudius.jpg', ARRAY['08-01', '10-01'], ARRAY['诞辰 · 前10年8月1日', '征服不列颠 · 43年'], ARRAY['birth', 'event'], '出兵不列颠时，是你替他在迷雾里指的路。', ARRAY['不列颠向导', '史官校对'], ARRAY['出兵不列颠时，是你替他在迷雾里指的路。', '他写的历史没人敢校订，除了你——你替他抹掉了几处尴尬。']),
  (54, '加尔巴', 'Galba', '前3—69', '古罗马', '罗马', '皇帝', ARRAY['帝王', '罗马', '军事'], '罗马皇帝，尼禄死后于高龄起兵称帝，开启了动荡的四帝之年，统治仅数月便遇弑。', '起兵粮官', '', 'assets/figures/galba.jpg', ARRAY['12-24', '06-09'], ARRAY['诞辰 · 前3年12月24日', '称帝 · 68年6月9日'], ARRAY['birth', 'event'], '他起兵那年，军粮的账本就在你手里，多一斗少一斗你说了算。', ARRAY['起兵粮官', '老兵酒友'], ARRAY['他起兵那年，军粮的账本就在你手里，多一斗少一斗你说了算。', '你和他一样，是军营里熬到白头的老伙计，酒壶常对半分。']),
  (55, '奥托', 'Otho', '32—69', '古罗马', '罗马', '皇帝', ARRAY['帝王', '罗马', '军事'], '罗马皇帝，四帝之年中的第二位。原为近卫军长官，称帝后在与维特里乌斯的争夺中兵败自尽。', '近卫军同袍', '', 'assets/figures/otho.jpg', ARRAY['04-28', '01-15'], ARRAY['诞辰 · 32年4月28日', '称帝 · 69年1月15日'], ARRAY['birth', 'event'], '你们同睡一间营房，醒来时一个竟成了皇帝。', ARRAY['近卫军同袍', '镜前侍从'], ARRAY['你们同睡一间营房，醒来时一个竟成了皇帝。', '他爱照镜子，镜前的灰尘与烛台，归你天天擦。']),
  (56, '维特里乌斯', 'Vitellius', '15—69', '古罗马', '罗马', '皇帝', ARRAY['帝王', '罗马', '军事'], '罗马皇帝，四帝之年中的第三位。以奢靡与贪食著称，短暂统治后被韦斯巴芗的军队击败并处死。', '宴席采买', '', 'assets/figures/vitellius.jpg', ARRAY['09-24', '04-19'], ARRAY['诞辰 · 15年9月24日', '称帝 · 69年4月19日'], ARRAY['birth', 'event'], '他一日三餐的排场，都是你一手张罗采买。', ARRAY['宴席采买', '御厨下手'], ARRAY['他一日三餐的排场，都是你一手张罗采买。', '御厨里你刀工最好，却最不爱声张，切好的鹅肝总先送他。']),
  (57, '韦斯巴芗', 'Vespasian', '9—79', '古罗马', '罗马', '皇帝', ARRAY['帝王', '罗马', '军事'], '罗马皇帝，弗拉维王朝开创者。他结束内乱、兴建斗兽场前身，并以务实节俭的作风扭转了帝国财政。', '斗兽场监工', '', 'assets/figures/vespasian.jpg', ARRAY['11-17', '07-01'], ARRAY['诞辰 · 9年11月17日', '称帝 · 69年7月1日'], ARRAY['birth', 'event'], '他兴建斗兽场，工地的钥匙你手里攥着一把。', ARRAY['斗兽场监工', '税吏旧识'], ARRAY['他兴建斗兽场，工地的钥匙你手里攥着一把。', '早年收税那些年，你和他拍过桌子也喝过酒，谁也不欠谁。']),
  (58, '提图斯', 'Titus', '39—81', '古罗马', '罗马', '皇帝', ARRAY['帝王', '罗马', '军事'], '罗马皇帝，韦斯巴芗之子。在位仅两年，却以镇压犹太起义、完成斗兽场兴建而留名，深得民心。', '围城副将', '', 'assets/figures/titus.jpg', ARRAY['12-30', '06-23'], ARRAY['诞辰 · 39年12月30日', '继位 · 79年6月23日'], ARRAY['birth', 'throne'], '耶路撒冷城下，你是他最信得过的副手，传令的快马你骑最多。', ARRAY['围城副将', '工坊匠首'], ARRAY['耶路撒冷城下，你是他最信得过的副手，传令的快马你骑最多。', '斗兽场完工那天，匠人们举你为头，说没有你搬不动那块石。']),
  (59, '图密善', 'Domitian', '51—96', '古罗马', '罗马', '皇帝', ARRAY['帝王', '罗马', '军事'], '罗马皇帝，弗拉维王朝末代君主。他加强集权与边境防御，后期统治趋向猜忌，最终遇刺身亡。', '禁卫随从', '', 'assets/figures/domitian.jpg', ARRAY['10-24', '09-14'], ARRAY['诞辰 · 51年10月24日', '继位 · 81年9月14日'], ARRAY['birth', 'throne'], '他疑心重，只肯让你近身递信，旁人一概挡在门外。', ARRAY['禁卫随从', '边境信使'], ARRAY['他疑心重，只肯让你近身递信，旁人一概挡在门外。', '边报往来，你是跑得最勤的那个，靴底磨穿两双。']),
  (60, '查理曼', 'Charlemagne', '742—814', '中世纪', '法兰克', '皇帝', ARRAY['帝王', '中世纪', '军事'], '法兰克国王，800年加冕为罗马人的皇帝。他统一西欧大片疆土、推动加洛林文艺复兴，被视为神圣罗马帝国的奠基者。', '宫廷乐师', '', 'assets/figures/charlemagne.jpg', ARRAY['04-02', '12-25'], ARRAY['诞辰 · 742年4月2日', '加冕皇帝 · 800年12月25日'], ARRAY['birth', 'event'], '他爱在宴上听你奏琴，曲子由你定，错一个音他也不恼。', ARRAY['宫廷乐师', '账房先生'], ARRAY['他爱在宴上听你奏琴，曲子由你定，错一个音他也不恼。', '帝国太大，他的账只有你算得清，金币入库先过你的手。'])
